export interface CopyButtonProps extends ComponentPropsWithoutRef<'button'> {
  copiedContent?: ReactNode
  copiedLabel?: string
  errorContent?: ReactNode
  errorLabel?: string
  label?: string
  resetAfter?: number
  target?: string
  toast?: boolean
  value?: string
  variant?: 'default' | 'destructive' | 'ghost' | 'link' | 'outline' | 'secondary'
  size?: 'default' | 'icon' | 'lg' | 'sm'
}

export const CopyButton = ({
  children = 'Copy',
  className,
  copiedContent,
  copiedLabel = 'Copied to clipboard',
  errorContent,
  errorLabel = 'Could not copy to clipboard',
  label = 'Copy to clipboard',
  onClick,
  resetAfter = 2000,
  size = 'default',
  target,
  toast = false,
  value,
  variant = 'outline',
  ...props
}: CopyButtonProps) => {
  const [state, setState] = useState<'copied' | 'error' | 'idle'>('idle')
  const resetTimerRef = useRef<ReturnType<typeof globalThis.setTimeout>>(undefined)

  useEffect(() => () => {
    globalThis.clearTimeout(resetTimerRef.current)
  }, [])

  const handleClick = async (event: ReactMouseEvent<HTMLButtonElement>) => {
    onClick?.(event)

    if (event.defaultPrevented) return

    const button = event.currentTarget
    const text = resolveCopyText(target, value)

    try {
      if (text === undefined) throw new Error(errorLabel)

      await navigator.clipboard.writeText(text)

      setState('copied')

      button.dispatchEvent(new CustomEvent('ui:copy-success', {
        bubbles: true,
        detail: { value: text }
      }))

      dispatchCopyToast(toast, copiedLabel, 'success')
    } catch (error) {
      setState('error')

      button.dispatchEvent(new CustomEvent('ui:copy-error', {
        bubbles: true,
        detail: { error }
      }))

      dispatchCopyToast(toast, errorLabel, 'destructive')
    }

    globalThis.clearTimeout(resetTimerRef.current)

    resetTimerRef.current = globalThis.setTimeout(() => {
      setState('idle')
    }, resetAfter)
  }

  const accessibleLabel = {
    copied: copiedLabel,
    error: errorLabel,
    idle: label
  }[state]

  return (
    <Button
      aria-label={accessibleLabel}
      className={composeClassName('ui-copy-button', className)}
      data-slot="copy-button"
      data-state={state}
      data-ui-copy-button
      onClick={handleClick}
      size={size}
      variant={variant}
      {...props}
    >
      <span aria-hidden="true" data-slot="copy-idle" hidden={state !== 'idle'}>{children}</span>
      <span aria-hidden="true" data-slot="copy-copied" hidden={state !== 'copied'}>
        {resolveCopyFeedback(copiedContent, copiedLabel)}
      </span>
      <span aria-hidden="true" data-slot="copy-error" hidden={state !== 'error'}>
        {resolveCopyFeedback(errorContent, errorLabel)}
      </span>
    </Button>
  )
}

