interface TourStep { content: string, target: string, title?: string }

interface Props extends HTMLAttributes<'div'> {
  class?: string | null
  className?: string
  closeLabel?: string
  nextLabel?: string
  steps?: TourStep[]
}

const {
  class: classProp = '',
  className = '',
  closeLabel = 'Done',
  nextLabel = 'Next',
  steps = [],
  ...rest
} = Astro.props

