export interface QRCodeProps extends ComponentPropsWithoutRef<'figure'> {
  size?: number
  src?: string
  value?: string
}

export const QRCode = ({
  children,
  className,
  size = 160,
  src,
  style,
  value,
  ...props
}: QRCodeProps) => {
  const qrSvg = !src && value ? renderSVG(value) : null

  const qrSrc = qrSvg ?
    `data:image/svg+xml;utf8,${encodeURIComponent(qrSvg)}` :
    src

