              alt={value ? `QR code for ${value}` : 'QR code'}
              className="ui-qr-code__image"
              height={size}
              src={qrSrc}
              width={size}
            />
          ) :
          (
            children
          )}
      </div>
      {value && <figcaption className="ui-qr-code__value">{value}</figcaption>}
    </figure>
  )
}

