export type LumenIllustrationTone = 'accent' | 'auto' | 'brand' | 'neutral'
export type LumenIllustrationVariant = 'empty' | 'error' | 'offline' | 'success'

export interface LumenIllustrationProps extends ViewProps {
  label?: string
  ref?: Ref<HostInstance>
  size?: LumenIllustrationSize
  tone?: LumenIllustrationTone
  variant?: LumenIllustrationVariant
}

const illustrationPoints = (points: readonly number[]): string => {
  const pairs: string[] = []

  for (let index = 0; index < points.length; index += 2) {
    pairs.push(`${String(points[index])},${String(points[index + 1])}`)
  }

  return pairs.join(' ')
}

const renderIllustrationElement = (
  element: LumenIllustrationElement,
  color: string,
  index: number,
  strokeWidth: number
): ReactElement => {
  const shared = {
    fill: 'none',
    stroke: color,
    strokeLinecap: 'round' as const,
    strokeLinejoin: 'round' as const,
    strokeWidth
  }

  if (element.kind === 'circle') {
    return <Circle key={index} {...shared} cx={element.cx} cy={element.cy} r={element.r} />
  }

  if (element.kind === 'rounded-rect') {
    return (
      <Rect
        key={index}
        {...shared}
        height={element.height}
        rx={element.radius}
        transform={`translate(${element.x} ${element.y})`}
        width={element.width}
      />
    )
  }

  const points = illustrationPoints(element.points)

  if (element.kind === 'line') {
    return (
      <Line
        key={index}
        {...shared}
        x1={element.points[0]}
        x2={element.points[2]}
        y1={element.points[1]}
        y2={element.points[3]}
      />
    )
  }

  return element.kind === 'polygon' ?
    <Polygon key={index} {...shared} points={points} /> :
    <Polyline key={index} {...shared} points={points} />
}

export const LumenIllustration = ({
  label,
  ref,
  size = 'md',
  style,
  tone = 'auto',
  variant = 'empty',
  ...props
}: LumenIllustrationProps): ReactElement => {
  const theme = useLumenTheme()
  const dimension = resolveLumenIllustrationSize(size)

  const semanticColor = {
    empty: theme.colors.brand,
    error: theme.colors.danger,
    offline: theme.colors.inkMuted,
    success: theme.colors.success
  }[variant]

  const color = tone === 'auto' ?
    semanticColor :
    {
      accent: theme.colors.accent,
      brand: theme.colors.brand,
      neutral: theme.colors.inkMuted
    }[tone]

  const strokeWidth = lumenGraphicStrokeWidths.standard
  const artwork = lumenIllustrations[variant]

  return (
    <View
      ref={ref}
      {...props}
      accessible={Boolean(label)}
      accessibilityElementsHidden={!label}
      accessibilityLabel={label}
      accessibilityRole={label ? 'image' : undefined}
      importantForAccessibility={label ? 'yes' : 'no-hide-descendants'}
      style={[{ alignItems: 'center', height: dimension, justifyContent: 'center', position: 'relative', width: dimension }, style]}
    >
      <Svg height={dimension} viewBox="0 0 120 120" width={dimension}>
        <Circle
          cx="60"
          cy="60"
          fill={color}
          fillOpacity={lumenGraphicOpacities.wash}
          r="48"
        />
        {artwork.elements.map((element, index) => renderIllustrationElement(element, color, index, strokeWidth))}
      </Svg>
    </View>
  )
}

export interface LumenDisclosureProps extends Omit<ViewProps, 'children'> {
  children: ReactNode
  description?: string
  disabled?: boolean
  expanded: boolean
  graphic?: ReactNode
  onExpandedChange: (expanded: boolean) => void
  ref?: Ref<HostInstance>
  title: string
