            null}
        </View>
        <Text
          accessibilityElementsHidden
          importantForAccessibility="no-hide-descendants"
          style={{ color: theme.colors.inkSoft, fontSize: theme.fontSizes.lg }}
        >
          {expanded ? '−' : '+'}
        </Text>
      </Pressable>
      {state.contentVisible ?
