        {...sharedFieldProps}
        label={endLabel}
        {...(endMinimum ? { minimumDate: endMinimum } : {})}
        onValueChange={end => {
          onValueChange(resolveLumenDateRangeEndChange(value, end, minimumDate, maximumDate))
        }}
        value={value.end}
      />
      <DateSupportingText
        {...(description ? { description } : {})}
        {...(errorMessage ? { errorMessage } : {})}
      />
    </View>
  )
}

