import { describe, expect, test } from 'vitest'

import {
  clampLumenDate,
  formatLumenDateDisplayValue,
  formatLumenDateInputValue,
  parseLumenDateInputValue,
  resolveLumenDateBounds,
  resolveLumenDatePickerValue,
  resolveLumenDateRangeEndChange,
  resolveLumenDateRangeStartChange,
  resolveLumenSearchFieldState
} from './form-recipes.js'

describe('Lumen React Native form component recipes', () => {
  test('shows the clear action only for editable non-empty queries', () => {
    expect(resolveLumenSearchFieldState('lumen', true)).toEqual({
      opacity: 1,
      showClearAction: true
    })
    expect(resolveLumenSearchFieldState('', true).showClearAction).toBe(false)
    expect(resolveLumenSearchFieldState('lumen', false)).toEqual({
      opacity: 0.52,
      showClearAction: false
    })
  })

  test('normalizes and clamps picker dates to inclusive bounds', () => {
    const minimum = new Date(2026, 7, 10)
    const maximum = new Date(2026, 7, 20)

    expect(clampLumenDate(new Date(2026, 7, 5, 18), minimum, maximum)).toEqual(minimum)
    expect(clampLumenDate(new Date(2026, 7, 15, 18), minimum, maximum)).toEqual(new Date(2026, 7, 15))
    expect(resolveLumenDatePickerValue(null, minimum, maximum, new Date(2026, 7, 25))).toEqual(maximum)
    expect(resolveLumenDateBounds(maximum, minimum)).toEqual({
      maximumDate: maximum,
      minimumDate: maximum
    })
    expect(resolveLumenDateBounds(new Date(Number.NaN), maximum)).toEqual({ maximumDate: maximum })
    expect(resolveLumenDateBounds(minimum, new Date(Number.NaN))).toEqual({ minimumDate: minimum })
    expect(resolveLumenDatePickerValue(new Date(Number.NaN), minimum, maximum, minimum)).toEqual(minimum)
  })

  test('uses the placeholder without formatting an invalid controlled date', () => {
    const formatter = (date: Date): string => date.toISOString()

    expect(formatLumenDateDisplayValue(new Date(Number.NaN), 'Select a date', formatter))
      .toBe('Select a date')
  })

  test('keeps a controlled date range ordered as either boundary changes', () => {
    const initial = {
      end: new Date(2026, 7, 12),
      start: new Date(2026, 7, 10)
    }
    const movedStart = resolveLumenDateRangeStartChange(initial, new Date(2026, 7, 15))

    expect(movedStart).toEqual({
      end: new Date(2026, 7, 15),
      start: new Date(2026, 7, 15)
    })
    expect(resolveLumenDateRangeEndChange(movedStart, new Date(2026, 7, 8))).toEqual(movedStart)
  })

  test('round-trips valid browser date input without timezone conversion', () => {
    expect(formatLumenDateInputValue(new Date(2026, 7, 26, 23, 45))).toBe('2026-08-26')
    expect(parseLumenDateInputValue('2026-08-26')).toEqual(new Date(2026, 7, 26))
    expect(parseLumenDateInputValue('2026-02-30')).toBeNull()
    expect(parseLumenDateInputValue('08/26/2026')).toBeNull()
  })
})

export interface LumenSearchFieldState {
  opacity: number
  showClearAction: boolean
}

export const resolveLumenSearchFieldState = (
  value: string,
  editable: boolean
): LumenSearchFieldState => ({
  opacity: editable ? 1 : 0.52,
  showClearAction: editable && value.length > 0
})

export interface LumenDateRangeValue {
  end: Date | null
  start: Date | null
}

export const isValidLumenDate = (value: Date | null | undefined): value is Date => (
  value !== null && value !== undefined && Number.isFinite(value.getTime())
)

const normalizeLumenDate = (value: Date): Date => (
  isValidLumenDate(value) ? new Date(value.getFullYear(), value.getMonth(), value.getDate()) : new Date(0)
)

export const formatLumenDateDisplayValue = (
  value: Date | null,
  placeholder: string,
  formatter: (date: Date) => string
): string => isValidLumenDate(value) ? formatter(value) : placeholder

const padLumenDatePart = (value: number): string => String(value).padStart(2, '0')

export const formatLumenDateInputValue = (value: Date): string => {
  const normalized = normalizeLumenDate(value)

  return `${normalized.getFullYear()}-${padLumenDatePart(normalized.getMonth() + 1)}-${padLumenDatePart(normalized.getDate())}`
}

export const parseLumenDateInputValue = (value: string): Date | null => {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value)

  if (!match) return null

  const year = Number(match[1])
  const month = Number(match[2]) - 1
  const day = Number(match[3])
  const date = new Date(year, month, day)

  if (date.getFullYear() !== year || date.getMonth() !== month || date.getDate() !== day) return null

  return date
}

export interface LumenDateBounds {
  maximumDate?: Date
  minimumDate?: Date
}

export const resolveLumenDateBounds = (
  minimumDate?: Date,
  maximumDate?: Date
): LumenDateBounds => {
  const bounds: LumenDateBounds = {}

  if (isValidLumenDate(minimumDate)) bounds.minimumDate = normalizeLumenDate(minimumDate)

  if (isValidLumenDate(maximumDate)) bounds.maximumDate = normalizeLumenDate(maximumDate)

  if (bounds.minimumDate && bounds.maximumDate && bounds.maximumDate < bounds.minimumDate) {
    bounds.maximumDate = bounds.minimumDate
  }

  return bounds
}

export const clampLumenDate = (
  value: Date,
  minimumDate?: Date,
  maximumDate?: Date
): Date => {
  const normalizedValue = normalizeLumenDate(value)

  const { maximumDate: normalizedMaximum, minimumDate: normalizedMinimum } = resolveLumenDateBounds(
    minimumDate,
    maximumDate
  )

  if (normalizedMinimum && normalizedValue < normalizedMinimum) return normalizedMinimum

  if (normalizedMaximum && normalizedValue > normalizedMaximum) return normalizedMaximum

  return normalizedValue
}

export const resolveLumenDatePickerValue = (
  value: Date | null,
  minimumDate?: Date,
  maximumDate?: Date,
  fallback = new Date()
): Date => clampLumenDate(isValidLumenDate(value) ? value : fallback, minimumDate, maximumDate)

export const resolveLumenDateRangeEndMinimum = (
  start: Date | null,
  minimumDate?: Date
): Date | undefined => {
  if (!start) return minimumDate

  if (!minimumDate || start > minimumDate) return start

  return minimumDate
}

export const resolveLumenDateRangeStartChange = (
  value: LumenDateRangeValue,
  start: Date,
  minimumDate?: Date,
  maximumDate?: Date
): LumenDateRangeValue => {
  const nextStart = clampLumenDate(start, minimumDate, maximumDate)
  const nextEnd = value.end && normalizeLumenDate(value.end) < nextStart ? nextStart : value.end

  return { end: nextEnd, start: nextStart }
}

export const resolveLumenDateRangeEndChange = (
  value: LumenDateRangeValue,
  end: Date,
  minimumDate?: Date,
  maximumDate?: Date
): LumenDateRangeValue => {
  const effectiveMinimum = resolveLumenDateRangeEndMinimum(value.start, minimumDate)

  return {
    end: clampLumenDate(end, effectiveMinimum, maximumDate),
    start: value.start
  }
}

