import { describe, expect, test } from 'vitest'

import {
  createLumenHookToast,
  getNextLumenThemeScheme,
  normalizeLumenHookSelectionOptions,
  updateLumenHookToast
} from './hook-recipes.js'

describe('React Native hook recipes', () => {
  test('normalizes primitive and structured native selection options', () => {
    expect(normalizeLumenHookSelectionOptions([
      'overview',
      { disabled: true, label: 'Activity', value: 'activity' }
    ])).toEqual([
      { label: 'overview', value: 'overview' },
      { disabled: true, label: 'Activity', value: 'activity' }
    ])
  })

  test('toggles between the supported explicit native schemes', () => {
    expect(getNextLumenThemeScheme('light')).toBe('dark')
    expect(getNextLumenThemeScheme('dark')).toBe('light')
  })

  test('creates and updates stable toast records', () => {
    const toast = createLumenHookToast('toast-1', { title: 'Saved' })

    expect(toast).toEqual({ id: 'toast-1', title: 'Saved', variant: 'default' })
    expect(updateLumenHookToast(toast, {
      description: 'Available offline',
      variant: 'success'
    })).toEqual({
      description: 'Available offline',
      id: 'toast-1',
      title: 'Saved',
      variant: 'success'
    })
  })
})

export interface LumenHookSelectionOption<Value extends number | string> {
  disabled?: boolean
  label: string
  value: Value
}

export interface LumenHookToastDetail {
  description?: string
  duration?: number
  title: string
  variant?: 'default' | 'destructive' | 'success' | 'warning'
}

export interface LumenHookToastRecord extends LumenHookToastDetail {
  id: string
}

export const normalizeLumenHookSelectionOptions = <Value extends number | string>(
  options: readonly (LumenHookSelectionOption<Value> | Value)[]
): readonly LumenHookSelectionOption<Value>[] => options.map(option => (
  typeof option === 'object' ? option : { label: String(option), value: option }
))

export const getNextLumenThemeScheme = (scheme: 'dark' | 'light'): 'dark' | 'light' => (
  scheme === 'dark' ? 'light' : 'dark'
)

export const createLumenHookToast = (
  id: string,
  detail: LumenHookToastDetail
): LumenHookToastRecord => ({
  ...detail,
  id,
  variant: detail.variant ?? 'default'
})

export const updateLumenHookToast = (
  toast: LumenHookToastRecord,
  detail: Partial<LumenHookToastDetail>
): LumenHookToastRecord => ({ ...toast, ...detail, id: toast.id })

