import { lumenIconNames } from './icons.generated.js'
import {
  createLumenTheme,
  lumenDarkTheme,
  lumenLightTheme,
  type LumenTheme
} from './theme.js'
import { lumenChartColorTokens, lumenColorTokens } from './tokens.generated.js'

vi.mock('react-native-svg', () => ({
  Circle: () => null,
  Ellipse: () => null,
  Line: () => null,
  Path: () => null,
