    expect(resolveLumenImageAspectRatio(16 / 9)).toBe(16 / 9)
    expect(resolveLumenImageAspectRatio(0)).toBeUndefined()
    expect(resolveLumenImageAspectRatio(-1)).toBeUndefined()
    expect(resolveLumenImageAspectRatio(Number.NaN)).toBeUndefined()
    expect(resolveLumenImageAspectRatio(Number.POSITIVE_INFINITY)).toBeUndefined()
    expect(resolveLumenImageAspectRatio(undefined)).toBeUndefined()
  })

  test('maps image radii to canonical tokens', () => {
    expect(resolveLumenImageRadius(lumenRadii, 'none')).toBe(0)
    expect(resolveLumenImageRadius(lumenRadii, 'sm')).toBe(lumenRadii.sm)
    expect(resolveLumenImageRadius(lumenRadii, 'md')).toBe(lumenRadii.md)
    expect(resolveLumenImageRadius(lumenRadii, 'lg')).toBe(lumenRadii.lg)
    expect(resolveLumenImageRadius(lumenRadii, 'full')).toBe(lumenRadii.full)
  })
})

import { type ReactElement, type Ref } from 'react'
import {
  type HostInstance,
  Image,
  type ImageProps,
  type ImageSourcePropType,
  type ImageStyle } from 'react-native'

import {
  resolveLumenImageAspectRatio,
  resolveLumenImageRadius
} from './media-recipes.js'
import { useLumenTheme } from './theme-context.js'

export type LumenImageFit = 'contain' | 'cover'
export type LumenImageRadius = 'full' | 'lg' | 'md' | 'none' | 'sm'

export interface LumenImageProps extends Omit<
  ImageProps,
  'accessibilityLabel' | 'accessible' | 'resizeMode' | 'source'
> {
  aspectRatio?: number
  decorative?: boolean
  fit?: LumenImageFit
  label?: string
  radius?: LumenImageRadius
  ref?: Ref<HostInstance>
  source: ImageSourcePropType
}

export const LumenImage = ({
  aspectRatio,
  decorative,
  fit = 'cover',
  label,
  radius = 'lg',
  ref,
  style,
  ...props
}: LumenImageProps): ReactElement => {
  const theme = useLumenTheme()
  const isDecorative = decorative ?? !label
  const safeAspectRatio = resolveLumenImageAspectRatio(aspectRatio)

  const imageStyle: ImageStyle = {
    ...(safeAspectRatio === undefined ? {} : { aspectRatio: safeAspectRatio }),
    borderRadius: resolveLumenImageRadius(theme.radii, radius),
    maxWidth: '100%',
    width: '100%'
  }

  return (
    <Image
      ref={ref}
      {...props}
      accessibilityElementsHidden={isDecorative}
      accessibilityLabel={isDecorative ? undefined : label}
      accessibilityRole={isDecorative ? undefined : 'image'}
      accessible={!isDecorative}
      importantForAccessibility={isDecorative ? 'no-hide-descendants' : 'yes'}
      resizeMode={fit}
      style={[imageStyle, style]}
    />
  )
}

import type { LumenImageRadius } from './media-components.js'
import type { LumenTheme } from './theme.js'

export const resolveLumenImageAspectRatio = (
  aspectRatio: number | undefined
): number | undefined => {
  if (aspectRatio === undefined || !Number.isFinite(aspectRatio) || aspectRatio <= 0) {
    return undefined
  }

  return aspectRatio
}

export const resolveLumenImageRadius = (
  radii: LumenTheme['radii'],
  radius: LumenImageRadius
): number => radius === 'none' ? 0 : radii[radius]

