const menuWidth = 240

/** An anchored action menu with native modal focus containment and labeled item states. */
export const LumenMenu = ({
  accessibilityLabel,
  items,
  trigger
}: LumenMenuProps): ReactElement => {
  const theme = useLumenTheme()
  const insets = useSafeAreaInsets()
  const triggerRef = useRef<ComponentRef<typeof Pressable>>(null)
  const { height: windowHeight, width: windowWidth } = useWindowDimensions()

  const [position, setPosition] = useState<LumenMenuPosition>({
    left: theme.spacing.lg,
    top: theme.spacing.lg
  })

  const [visible, setVisible] = useState(false)

  const open = (): void => {
    triggerRef.current?.measureInWindow((x, y, width, height) => {
      setPosition(resolveLumenMenuPosition({
        anchorHeight: height,
        anchorWidth: width,
        anchorX: x,
        anchorY: y,
        bottomInset: insets.bottom,
        itemCount: items.length,
        leftInset: insets.left,
        margin: theme.spacing.lg,
        menuWidth,
        rightInset: insets.right,
        topInset: insets.top,
        windowHeight,
        windowWidth
      }))

      setVisible(true)
    })
  }

  return (
    <>
      <Pressable
        ref={triggerRef}
        accessibilityLabel={accessibilityLabel}
        accessibilityRole="button"
        accessibilityState={{ expanded: visible }}
        onPress={open}
      >
        {trigger}
      </Pressable>
      <Modal
        animationType="fade"
        onRequestClose={() => {
          setVisible(false)
        }}
        transparent
        visible={visible}
      >
        <Pressable
          accessibilityViewIsModal
          onPress={() => {
            setVisible(false)
          }}
          style={{ flex: 1 }}
        >
          <View
            accessibilityLabel={accessibilityLabel}
            accessibilityRole="menu"
            style={{
              backgroundColor: theme.colors.surface,
              borderColor: theme.colors.line,
              borderRadius: theme.radii.md,
              borderWidth: 1,
              left: position.left,
              padding: theme.spacing.sm,
              position: 'absolute',
              top: position.top,
              width: menuWidth
            }}
          >
            {items.map(item => (
              <Pressable
                key={item.label}
                accessibilityRole="menuitem"
                accessibilityState={{ disabled: item.disabled }}
                disabled={item.disabled}
                onPress={() => {
                  setVisible(false)

                  item.onPress()
                }}
                style={({ pressed }): ViewStyle => ({
                  backgroundColor: pressed ? theme.colors.surfaceMuted : 'transparent',
                  borderRadius: theme.radii.sm,
                  minHeight: 44,
                  opacity: item.disabled ? 0.52 : 1,
                  paddingHorizontal: theme.spacing.md,
                  paddingVertical: theme.spacing.md
                })}
              >
                <Text
                  style={{
                    color: item.destructive ? theme.colors.danger : theme.colors.ink,
                    fontSize: theme.fontSizes.sm
                  }}
                >
                  {item.label}
                </Text>
              </Pressable>
            ))}
          </View>
        </Pressable>
      </Modal>
    </>
  )
}

