import SwiftUI

private struct LumenAlertDialogModifier: ViewModifier {
    @Binding var isPresented: Bool

    let cancelLabel: LocalizedStringKey
    let confirmDisabled: Bool
    let confirmLabel: LocalizedStringKey
    let confirmLoading: Bool
    let confirmLoadingAccessibilityValue: LumenTextContent
    let confirmRole: ButtonRole?
    let description: LocalizedStringKey?
    let onConfirm: () -> Void
    let title: LocalizedStringKey

    func body(content: Content) -> some View {
        content.alert(title, isPresented: $isPresented) {
            Button(cancelLabel, role: .cancel) {}
            Button(role: confirmRole, action: onConfirm) {
                HStack(spacing: LumenSpacing.sm) {
                    if confirmLoading {
#if os(tvOS)
                        ProgressView()
#else
                        ProgressView()
                            .controlSize(.small)
#endif
                    }
                    Text(confirmLabel)
                }
            }
            .disabled(confirmDisabled || confirmLoading)
            .accessibilityValue(confirmLoading ? confirmLoadingAccessibilityValue.text : Text(""))
        } message: {
            if let description {
                Text(description)
            }
        }
    }
}

